inlineScript.scriptBlock:
 this.showScreenBtn = function()
 {
 	if(this.context.options.screenVisibility == "screen")
 	{
 		this.ui.get("closeBtn").setVisible(true,true);	
 		this.ui.get("backBtn").setVisible(true,true);	
 		
 		this.ui.get("isLiquidated").setVisible(false,true);
 		this.ui.get("saveState").setVisible(false,true);	
 		this.ui.get("submit").setVisible(false,true);	
 	
 	}
 	else
 	{
 		this.ui.get("closeBtn").setVisible(false,true);	
 		this.ui.get("backBtn").setVisible(false,true);
 		
 		this.ui.get("isLiquidated").setVisible(false,true);
 		this.ui.get("saveState").setVisible(true,true);	
 		this.ui.get("submit").setVisible(true,true);
 	}
 
 }


this.validateAction = function(){
	this.ui.get('actionList').setValid(false,'Please Select an action')
	return false
	if(!!this.context.options.selectedAction.get("value")){
	}else{
		this.ui.get('actionList').setValid(true)
		return true
	}
}

// on click of save btn, to validate not commited transactions before save.
this.ValidateTransaction = function () {
	if (this.context.options.ValidateTransaction && this.context.options.ValidateTransaction.get("value") == true) {
		if (this.context.options.amountAdvanced && this.context.options.amountAdvanced.get("value") > 0) {
			if (!!bpmext.ui.getView("/DC_Templete1/4/negotiatedExchangeRate")) {
				return bpmext.ui.getView("/DC_Templete1/4").CheckFieldIsEnabled();
			} else if (!!bpmext.ui.getView("/DC_Templete1/3/negotiatedExchangeRate")) {
				return bpmext.ui.getView("/DC_Templete1/3").CheckFieldIsEnabled();
			} else {
				return true;
			}
		}
		return true;
	}
	return true;
}
